Translate("zhCN", "the-hinterlands", {
	title = "辛特兰",
	aliases = { "辛特兰地区" },
	sections = {
		{
			title = "概述",
			text = [=[辛特兰是一片由青翠山丘、幽深森林和高耸悬崖构成的荒野，位于{link:arathi-highlands}阿拉希高地{/link}东北、{link:hillsbrad-foothills}希尔斯布莱德丘陵{/link}以东。很少有道路穿过这里，农田就更少了。数千年来，这里一直属于森林{link:trolls}巨魔{/link}，他们的神庙和阶梯状的城市至今仍矗立在山顶。在遥远西部的一座峭壁上矗立着{link:aerie-peak}鹰巢山{/link}，那是{red:wildhammer-clan}蛮锤{/red}{link:dwarves}矮人{/link}和他们的狮鹫的家园。在遥远的东南部海边，{link:revantusk-village}恶齿{/link}巨魔为{link:horde}部落{/link}守着一座村庄。在两者之间，是一片自相残杀的土地：三个除了血统之外毫无共同之处的巨魔部族，一座远离故乡的{link:high-elves}高等精灵{/link}小屋，而在东北部，有一棵巨树，绿龙族在那里守望。]=],
		},
		{
			title = "起源",
			text = [=[没有任何史书记载第一批{link:trolls}巨魔{/link}何时开始在这些山丘中建造。人们所知道的是，北方的森林曾是阿曼尼帝国的一部分，那是森林巨魔的国度，而阿曼尼从未原谅在更远的土地上定居的{link:high-elves}精灵{/link}。辛特兰的废墟城市是巨魔的作品，它们的祭坛比任何{link:humans}人类{/link}王国都要古老。{link:dwarves}矮人{/link}来得要晚得多。三锤之战后，蛮锤氏族离开了{link:grim-batol}格瑞姆巴托{/link}被玷污的厅堂，在{link:aerie-peak}鹰巢山{/link}建立了新家园。在那里，在巨魔的{link:razorfen-downs}高地{/link}上，他们驯服了野生的狮鹫，学会了飞翔。]=],
		},
		{
			title = "当今",
			text = [=[辛特兰没有唯一的主人。蛮锤{link:dwarves}矮人{/link}在他们的至高领主{link:falstad-wildhammer}弗斯塔德·蛮锤{/link}的统领下据守着{link:aerie-peak}鹰巢山{/link}。他们与{link:ironforge}铁炉堡{/link}血脉相连，是其盟友，但他们坚称自己不属于{link:alliance}联盟{/link}，与他们的友谊必须用行动来赢得。{link:revantusk-village}恶齿{/link}{link:trolls}巨魔{/link}以{link:horde}部落{/link}的名义据守着他们在东岸的村庄，他们对蛮锤矮人恨之入骨。{red:vilebranch-trolls}邪枝巨魔{/red}从他们的神庙中统治着南部和东北部。他们吃其他巨魔的肉，并把俘虏献给血神{link:hakkar}哈卡{/link}。{link:witherbark-trolls}枯木巨魔{/link}占据着西南部，在那里侍奉他们自己的一位蜘蛛之神。{link:skulk-rock}隐匿石{/link}那座旧部落营地中的软泥怪已蔓延到河谷之中，狼、枭兽和野生狮鹫捕猎一切会动的东西。]=],
		},
		{
			title = "居民",
			text = [=[• {b}蛮锤{link:dwarves}矮人{/link}。{/b}他们和他们的狮鹫住在{link:aerie-peak}鹰巢山{/link}。他们骄傲、喧闹、极其独立，记恨旧仇的时间比他们在{link:ironforge}铁炉堡{/link}的表亲更长。
• {b}{link:revantusk-village}恶齿{/link}{link:trolls}巨魔{/link}。{/b}{link:horde}部落{/link}的森林巨魔，他们在海边守着一座村庄，毫不留情地与邪枝巨魔作战。
• {b}邪枝巨魔。{/b}这片土地上最大也最野蛮的部族。他们的都城是{link:jintha-alor}辛萨罗{/link}，他们的女祭司在那里准备献给{link:hakkar}哈卡{/link}的祭品。
• {b}{link:witherbark-trolls}枯木巨魔{/link}。{/b}他们住在西南部的村庄和{link:shadra-alor}沙德拉洛{/link}。他们曾与部落并肩作战，后来又背叛了部落。
• {b}{link:quel-danil-lodge}奎尔丹尼{/link}的{link:high-elves}高等精灵{/link}。{/b}高谷的游侠和斥候在西部、矮人附近据守着一座狩猎小屋。
• {b}绿龙族。{/b}在东北部的{link:seradane}瑟拉丹{/link}，龙人和幼龙守卫着一棵巨树，不容任何人靠近。]=],
		},
		{
			title = "历史",
			text = [=[• {b}阿曼尼时代。{/b}在过去的纪元里，森林{link:trolls}巨魔{/link}作为一个伟大帝国的一部分统治着这些山丘。{link:troll-wars}巨魔战争{/link}打破了他们的力量，但巨魔从未离开。
• {b}三锤。{/b}三个氏族之间的战争结束后，蛮锤{link:dwarves}矮人{/link}放弃了{link:grim-batol}格瑞姆巴托{/link}，定居在{link:aerie-peak}鹰巢山{/link}。他们成了北方的狮鹫骑士。
• {b}{link:second-war}第二次战争{/link}。{/b}当{link:orcs}兽人{/link}{link:horde}部落{/link}向北进军时，{red:zul-jin}祖尔金{/red}统领下的阿曼尼巨魔加入了它，希望焚毁{link:quel-thalas}奎尔萨拉斯{/link}。蛮锤矮人为{link:alliance}联盟{/link}出战，与他们作对。部落曾一度在辛特兰占据阵地，其中包括{link:skulk-rock}隐匿石{/link}的营地。最终它放弃了这些阵地。
• {b}新的部落。{/b}在{link:thrall}萨尔{/link}的领导下，部落再次在森林巨魔中找到了朋友。{link:revantusk-village}恶齿{/link}部族加入了部落。{link:witherbark-trolls}枯木部族{/link}起初与部落并肩作战，后来背叛了它，{link:darkspear-trolls}暗矛巨魔{/link}则向北方送去严厉的警告作为回应。
• {b}当今。{/b}如今，恶齿巨魔等待着祖尔{link:ginro-hearthkindle}金{/link}归来，邪枝巨魔喂养着他们的{link:hakkar}血神{/link}，而鹰巢山的矮人清点着他们失去的每一只狮鹫。]=],
		},
		{
			title = "山丘传说",
			text = [=[• {link:revantusk-village}恶齿{/link}{link:trolls}巨魔{/link}说，辛特兰的三个巨魔部族只有两样共同之处：他们都是巨魔，他们都住在辛特兰。
• 在{link:aerie-peak}鹰巢山{/link}，如果一个新来者把蛮锤{link:dwarves}矮人{/link}称为“{link:alliance}联盟{/link}”，立刻就会被大声纠正。
• 在遥远的{link:stranglethorn-vale}荆棘谷{/link}海岸上发现的一则古老谜语，提到辛特兰海岸那道大瀑布脚下的水中藏着一批宝藏。
• 鹰巢山的一个醉醺醺的狮鹫骑士曾从坐骑上跌入{link:swamp-of-sorrows}悲伤沼泽{/link}中阿塔莱{link:temple-of-atal-hakkar}沉没的神庙{/link}，并活了下来，只要一杯酒的价钱就肯讲这个故事。]=],
		},
	},
})

Translate("zhCN", "aerie-peak", {
	title = "鹰巢山",
	sections = {
		{
			title = "概述",
			text = [=[鹰巢山是{red:wildhammer-clan}蛮锤{/red}{link:dwarves}矮人{/link}的要塞，建在{link:the-hinterlands}辛特兰{/link}西部边缘的一座峭壁上。它的中心是蛮锤城堡，至高领主在那里理政；城堡上方是巨大的狮鹫栖所，氏族的狮鹫在那里出生、长大并接受训练。这座城镇有一家旅店、铁匠、制皮匠，中央有一口井。这是一个喧闹、骄傲而严酷的地方。陌生人只有在证明了自己之后才会受到欢迎，而东方的{link:trolls}巨魔{/link}确保了没有哪个蛮锤矮人睡觉时手边没有斧子。]=],
		},
	},
})

Translate("zhCN", "revantusk-village", {
	title = "恶齿村",
