			text = [=[奎尔丹尼小屋是{link:high-elves}高等精灵{/link}的一座狩猎小屋，建在{link:the-hinterlands}辛特兰{/link}西部的树林之间，在{link:aerie-peak}鹰巢山{/link}以东不远处。高谷的游侠、斥候、神射手和信使在那里守望。他们远离{link:quel-thalas}奎尔萨拉斯{/link}，在蛮锤{link:dwarves}矮人{/link}中找到了朋友。这片土地上的{link:trolls}巨魔{/link}是他们的敌人。{link:revantusk-village}恶齿{/link}巨魔把这些精灵视为矮人正在缔结新{link:alliance}联盟{/link}的证据，而落入精灵手中的{link:witherbark-trolls}枯木巨魔{/link}则被当作囚犯关在小屋里。]=],
		},
	},
})

Translate("zhCN", "shindigger-s-camp", {
	title = "拉普索迪营地",
	aliases = { "辛迪格的营地" },
	sections = {
		{
			title = "概述",
			text = [=[拉普索迪营地是{link:the-hinterlands}辛特兰{/link}西部一座由酒桶和炊火构成的小营地，在{link:aerie-peak}鹰巢山{/link}以东，紧邻{link:quel-danil-lodge}奎尔丹尼小屋{/link}。它属于{link:rhapsody-shindigger}拉普索迪·铁铲{/link}，他曾是狮鹫栖所中最好的狮鹫骑士，自从{link:dwarves}矮人{/link}们辞退他之后，他就在这里酿造自己的酒。他并不独饮。一个名叫{link:gilveradin-sunchaser}基沃拉丁·猎日者{/link}的{link:high-elves}高等精灵{/link}在他旁边扎了营，此人热爱美酒胜过一切事业和王国。]=],
