Translate("zhCN", "skulk-rock", {
	title = "隐匿石",
	sections = {
		{
			title = "概述",
			text = [=[隐匿石是{link:the-hinterlands}辛特兰{/link}中部的一个洞穴和一座废弃的营地，位于一条河流的源头。{link:horde}部落{/link}曾在这里驻有一座基地，很久以前就放弃了这个地方。它留下的箱子里仍装着辛特兰蜂蜜酒，一种如今在任何地方都买不到的饮料。现在，绿色淤泥怪和翡翠软泥怪占据了这片废墟，传说有某个软泥怪首领在率领它们。蛮锤{link:dwarves}矮人{/link}想要清理这个地方，因为他们对它另有打算。附近曾发现过一台失事的、由{link:gnomes}侏儒{/link}制造的奇怪{link:ginro-hearthkindle}金{/link}属装置。]=],
		},
	},
})

Translate("zhCN", "jintha-alor", {
	title = "辛萨罗",
	sections = {
		{
			title = "概述",
			text = [=[辛萨罗是{red:vilebranch-trolls}邪枝巨魔{/red}的都城。它耸立在{link:the-hinterlands}辛特兰{/link}南部，是一座巨大的阶梯状石城，一层层台地向上攀升，直到顶上的一座圆形剧场。在顶端，{link:vile-priestess-hexx}邪恶祭司海克斯{/link}掌握着大权，由阿曼扎斯卫士护卫着。城中各处摆放着盛满污染之血的容器，其黑暗力量驱使邪枝{link:trolls}巨魔{/link}陷入疯狂。俘虏被带到这里献祭给{link:hakkar}哈卡{/link}。顶端附近，一个满是软泥怪的垃圾坑和一个狼穴等待着残骸。据说，在圆形剧场后面的一个洞穴里，有一枚来自巨魔统治诸帝国时代的古老的蛋。]=],
		},
	},
})

Translate("zhCN", "the-altar-of-zul", {
	title = "祖尔祭坛",
	sections = {
		{
			title = "概述",
			text = [=[祖尔祭坛是一座{link:trolls}巨魔{/link}神庙，位于邪枝领地的西部边缘，在{link:jintha-alor}辛萨罗{/link}西北。它的台阶通向一座高高的祭坛，邪枝巨魔在那里进行献祭。部族的两名守护者奇亚加和摩尔塔加照管着它。当年幼的狮鹫锐喙失踪时，{link:aerie-peak}鹰巢山{/link}的{link:dwarves}矮人{/link}担心他被带到了这里。当在祭坛上没有找到他时，他们松了一口气，因为他们知道邪枝巨魔在那里做些什么。]=],
		},
	},
})

Translate("zhCN", "shadra-alor", {
	title = "沙德拉洛",
	sections = {
		{
			title = "概述",
			text = [=[沙德拉洛是一座{link:trolls}巨魔{/link}神庙，位于{link:the-hinterlands}辛特兰{/link}西南部深处，在{link:witherbark-trolls}枯木巨魔{/link}的领地中。它是他们的蜘蛛之神{link:shadra}沙德拉{/link}的居所，它的树林中爬满了她的子嗣。枯木巨魔收集她的毒液，装在瓶子里保存在他们的村庄中。神庙的中心立着一座祭坛，如果在那里说出她的真名，女神本身就可能被召唤出来。神庙附近住着一个阿塔莱的流放者，一个被自己族人驱逐的祭司，他在枯木巨魔中间找到了一个苦涩的栖身之所。]=],
		},
	},
})

Translate("zhCN", "hiri-watha-and-zun-watha", {
	title = "西利瓦萨和祖瓦沙",
	aliases = { "西利瓦萨", "祖瓦沙" },
	sections = {
		{
			title = "概述",
			text = [=[西利瓦萨和祖瓦沙是{link:the-hinterlands}辛特兰{/link}西南部{link:witherbark-trolls}枯木巨魔{/link}的两座村庄。它们比邪枝{link:trolls}巨魔{/link}的神庙城市小，但危险程度不相上下。它们的小屋里有关押俘虏的笼子，还有来自{link:shadra-alor}沙德拉洛{/link}蜘蛛的绿色毒液瓶。枯木巨魔曾与{link:horde}部落{/link}并肩作战，后来又背叛了它，{link:stranglethorn-vale}荆棘谷{/link}的{link:darkspear-trolls}暗矛巨魔{/link}没有忘记这件事。他们的使者{link:nimboya}尼姆布亚{/link}已把他的长矛送到北方，立在其中一座村庄里，矛上顶着枯木巨魔的头骨。]=],
		},
	},
})

Translate("zhCN", "agol-watha-and-shaol-watha", {
	title = "亚戈瓦萨和沙尔瓦萨",
	aliases = { "亚戈瓦萨", "沙尔瓦萨" },
	sections = {
		{
