Translate("zhCN", "seradane", {
	title = "瑟拉丹",
	sections = {
		{
			title = "概述",
			text = [=[瑟拉丹位于{link:the-hinterlands}辛特兰{/link}的遥远东北部，在{link:trolls}巨魔{/link}神庙之外的一处{link:razorfen-downs}高地{/link}洼谷中。那里耸立着一棵巨树。那是世界上少数几个让清醒的大地与{link:emerald-dream}翡翠梦境{/link}相接触的地方之一，德鲁伊把它算作{link:azeroth}艾泽拉斯{/link}上四棵这样的巨树之一。绿色龙人守卫着它的树根，巨大的绿龙守望着它的树冠。它们不与靠近的人谈判，无论巨魔还是{link:dwarves}矮人{/link}都不会心甘情愿地爬进它们的洼谷。]=],
