	},
})

Translate("zhCN", "the-overlook-cliffs", {
	title = "望海崖",
	sections = {
		{
			title = "概述",
			text = [=[望海崖是{link:the-hinterlands}辛特兰{/link}东部的高耸边缘，陆地在那里笔直地落入大海。瀑布从山丘上倾泻入海浪之中，岸边不远处散布着一些小岛。{link:witherbark-trolls}枯木{/link}俘虏{link:rin-ji}林吉{/link}曾把他的族人的一块石板藏在其中一座小岛上。{link:booty-bay}藏宝海湾{/link}的{link:gnomes}侏儒{/link}工程师曾选择悬崖之外的海岸线作为召回一台失事飞行器的安全地点。一则来自远方的古老谜语，提到那道大瀑布脚下的水中藏着一批宝藏。]=],
		},
	},
})

