			text = [=[关于对抗{link:dragonmaw-clan}龙喉氏族{/link}之战的故事中，提到一个名叫弗斯塔德的蛮锤狮鹫骑士，他在{link:second-war}第二次战争{/link}之后的岁月里曾在{link:grim-batol}格瑞姆巴托{/link}上空作战。那位骑士与{link:aerie-peak}鹰巢山{/link}的至高领主是否是同一个人，本条目所查阅的史书都没有明言。关于弗斯塔德是如何成为氏族统治者的，其他记载也很少。]=],
